def IsAssociatedPrime.{u_1, u_2} : {R : Type u_1} →
  [inst : CommSemiring R] → Ideal R → (M : Type u_2) → [inst_1 : AddCommMonoid M] → [Module R M] → Prop :=
fun {R} [CommSemiring R] I M [AddCommMonoid M] [Module R M] => ⊥.IsAssociatedPrime I
def associatedPrimes.{u_1, u_2} : (R : Type u_1) →
  [inst : CommSemiring R] → (M : Type u_2) → [inst_1 : AddCommMonoid M] → [Module R M] → Set (Ideal R) :=
fun R [CommSemiring R] M [AddCommMonoid M] [Module R M] => {I | IsAssociatedPrime I M}
@associatedPrimes.eq_singleton_of_isPrimary : ∀ {R : Type u_1} [inst : CommRing R] {I : Ideal R} [IsNoetherianRing R],
  I.IsPrimary → associatedPrimes R (R ⧸ I) = {I.radical}
@Submodule.mem_annihilator_span_singleton : ∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R]
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (g : M) (r : R), r ∈ (R ∙ g).annihilator ↔ r • g = 0

