@isAssociatedPrime_iff : ∀ {R : Type u_1} [inst : CommSemiring R] {I : Ideal R} {M : Type u_2}
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] [IsNoetherianRing R],
  IsAssociatedPrime I M ↔ I.IsPrime ∧ ∃ x, I = ⊥.colon {x}
@Submodule.isAssociatedPrime_iff : ∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {N : Submodule R M} {I : Ideal R} [IsNoetherianRing R],
  N.IsAssociatedPrime I ↔ I.IsPrime ∧ ∃ x, I = N.colon {x}
@associatedPrimes.subset_union_of_exact : ∀ {R : Type u_1} [inst : CommSemiring R] {M : Type u_2}
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {M' : Type u_3} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M']
  {f : M →ₗ[R] M'} {M'' : Type u_4} [inst_5 : AddCommMonoid M''] [inst_6 : Module R M''] {g : M' →ₗ[R] M''},
  Function.Injective ⇑f → Function.Exact ⇑f ⇑g → associatedPrimes R M' ⊆ associatedPrimes R M ∪ associatedPrimes R M''
@associatedPrimes.subset_of_injective : ∀ {R : Type u_1} [inst : CommSemiring R] {M : Type u_2}
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {M' : Type u_3} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M']
  {f : M →ₗ[R] M'}, Function.Injective ⇑f → associatedPrimes R M ⊆ associatedPrimes R M'
@IsAssociatedPrime.eq_radical : ∀ {R : Type u_1} [inst : CommRing R] {I J : Ideal R},
  I.IsPrimary → IsAssociatedPrime J (R ⧸ I) → J = I.radical
@isAssociatedPrime_iff_exists_injective_linearMap : ∀ {R : Type u_1} [inst : CommRing R] (I : Ideal R) (M : Type u_2)
  [inst_1 : AddCommGroup M] [inst_2 : Module R M] [IsNoetherianRing R],
  IsAssociatedPrime I M ↔ I.IsPrime ∧ ∃ f, Function.Injective ⇑f

